from collections import Counter, deque
def transform(grid):
    h,w=len(grid),len(grid[0]); bg=Counter(x for row in grid for x in row).most_common(1)[0][0]
    seen=set(); objs=[]
    for r in range(h):
      for c in range(w):
        col=grid[r][c]
        if col==bg or (r,c) in seen: continue
        q=[(r,c)]; seen.add((r,c)); cells=[]
        while q:
          y,x=q.pop(); cells.append((y,x))
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            yy,xx=y+dy,x+dx
            if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==col:
              seen.add((yy,xx)); q.append((yy,xx))
        if len(cells)>=3: objs.append((col,min(y for y,x in cells),max(y for y,x in cells),min(x for y,x in cells),max(x for y,x in cells)))
    out=[row[:] for row in grid]
    for r in range(h):
      for c in range(w):
        candidates=[o for o in objs if o[1]<=r<=o[2] and o[3]<=c<=o[4]]
        if candidates:
          # choose narrowest object bounding box
          o=min(candidates,key=lambda z:(z[2]-z[1]+1)*(z[4]-z[3]+1)); out[r][c]=o[0]
        elif grid[r][c]!=bg and not any(grid[r][c]==o[0] and o[1]<=r<=o[2] and o[3]<=c<=o[4] for o in objs): out[r][c]=bg
    return out
